// Synthetic browser fixture derived from the existing departure form test.
import {readFile} from 'node:fs/promises';
import {basicFixture} from './basic-page.mjs';
const product=JSON.parse(await readFile(new URL('../../examples/product.json',import.meta.url),'utf8'));
product.departures[0].prices[0]={adult:{currency:'KRW',amount:1000},child:{currency:'KRW',amount:500},infant:{currency:'KRW',amount:100},basis:'standard',fuelIncluded:true};
const target={productId:'812345',masterCode:'CJU-SYNTHETIC',title:product.title,account:'Fixture Operator'};
const options={savedScheduleId:'9001',divisionId:'9002',expectedAccountName:target.account,bookingStatus:'closed',departureSettings:[{index:0,minPax:1,maxPax:2,outboundOperatorLabel:'0B - 전용차량',returnOperatorLabel:'0B - 전용차량'}]};
const input=(id,val='',type='text')=>`<input id="${id}" type="${type}" value="${val}">`;
const select=(id,entries)=>`<div><select id="${id}" style="display:none">${entries.map(([v,t])=>`<option value="${v}">${t}</option>`).join('')}</select><input class="select-dropdown dropdown-trigger" readonly value="${entries[0][1]}" onclick="chooseOption(this)"></div>`;
const operator=id=>`<select id="${id}" hidden></select><span id="select2-${id}-container">선택해주세요</span><button type="button" role="combobox" aria-labelledby="select2-${id}-container" onclick="openOperator('${id}')">운영사</button><span class="select2-container" data-operator="${id}"><span class="select2-search select2-search--dropdown"><input class="select2-search__field" tabindex="-1" oninput="renderOperators(this)"></span><ul id="select2-${id}-results" role="tree" aria-expanded="false" aria-hidden="true"></ul></span>`;
const parent=basicFixture+`<div id="eoding-name">Fixture Operator</div><a href="/tour/master_product/812345/create_product/?from=812345">행사생성</a><script>document.querySelector('#id_2-title').value=${JSON.stringify(product.title)};document.querySelector('#id_2-status').value='2';document.querySelector('#id_2-master_code').value='CJU-SYNTHETIC';document.querySelector('#id_2-master_url').value='https://tenant.eoding-demo.com/master/812345';</script>`;
const eventHTML=`<meta charset="utf-8"><title>행사생성</title><div id="eoding-name">Fixture Operator</div><form id="create_product_form">
${input('id_master_product_id','812345','hidden')}${input('id_master_product_id','812345','hidden')}
${select('id_status',[['3','예약가능'],['4','예약마감']])}${input('id_title')}${input('id_currency_code','KRW')}
${select('id_schedule',[['','선택해주세요'],['9001','[#SC-FIXTURE] [1박2일] 가상 일정']])}
${select('id_product_division_label',[['9002','가상 구분값']])}${select('id_manager',[['9101','가상 담당자']])}${select('id_dept',[['9201','가상 부서']])}${select('id_dept2',[['9301','가상 팀']])}
${['adult','child','infant'].map(k=>input('id_'+k+'_price')+input('id_'+k+'_fuel_price')).join('')}${input('id_min_pax_count')}${input('id_max_pax_count')}
${input('start-date')}${input('end-date')}${input('id_selected_dates','','hidden')}<button id="create_schedule_calendar" type="button" onclick="calendar()">달력생성</button><div id="multi-calendar"></div>
${operator('id_depart_airline')}${operator('id_return_airline')}${input('id_apply_depart_to_return','','checkbox')}
${select('id_payment_full_flag',[['False','N'],['True','Y']])}${select('id_payment_deposit_flag',[['False','N'],['True','Y']])}${input('id_payment_deposit_person','0')}${input('id_payment_deposit_infant','','checkbox')}
${select('id_reward_type',[['0','정률(%)']])}${input('id_reward_value','0')}${select('id_use_custom_price',[['0','미사용']])}${input('id_default_contract_title')}${input('id_default_contract_id','','hidden')}${input('id_default_contract_id','','hidden')}${input('id_estimate_term_id','','hidden')}${input('id_form-TOTAL_FORMS','0','hidden')}
<button id="create_tour_product" type="button" onclick="fetch('/__fixture__/save',{method:'POST'})">행사만들기</button></form>
<script>document.getElementById('id_title').value=${JSON.stringify(product.title)};window.formMutations=0;document.addEventListener('input',()=>window.formMutations++);
function chooseOption(input){const s=input.previousElementSibling;const ul=document.createElement('ul');for(const o of s.options){const li=document.createElement('li');li.textContent=o.textContent;li.onclick=()=>{s.value=o.value;input.value=o.textContent;ul.remove()};ul.append(li)}document.body.append(ul)}
function openOperator(id){for(const r of document.querySelectorAll('[id^="select2-"][id$="-results"]')){r.setAttribute('aria-expanded','false');r.setAttribute('aria-hidden','true');r.previousElementSibling.querySelector('input').tabIndex=-1}const r=document.getElementById('select2-'+id+'-results');r.setAttribute('aria-expanded','true');r.setAttribute('aria-hidden','false');const search=r.previousElementSibling.querySelector('input');search.tabIndex=0;search.value='';r.replaceChildren();if(id==='id_return_airline'){const stale=document.getElementById('select2-id_depart_airline-results');window.oldOutboundVisibleWhileReturnOpen=stale.getAttribute('aria-expanded')==='false'&&stale.getAttribute('aria-hidden')==='true'&&stale.previousElementSibling.querySelector('input').tabIndex===-1&&!stale.hidden}}
function renderOperators(search){const r=search.closest('.select2-container').querySelector('[role="tree"]');const q=search.value;r.replaceChildren();if(q!=='0B')return;const li=document.createElement('li');li.setAttribute('role','treeitem');li.textContent='0B - 전용차량';li.onclick=()=>{const id=r.closest('.select2-container').dataset.operator;const s=document.getElementById(id);s.replaceChildren(new Option(li.textContent,'700',true,true));document.getElementById('select2-'+id+'-container').textContent=li.textContent;r.setAttribute('aria-expanded','false');r.setAttribute('aria-hidden','true');search.tabIndex=-1};r.append(li)}
function calendar(){const root=document.getElementById('multi-calendar');root.replaceChildren();const date=document.getElementById('start-date').value;const [year,month,day]=date.split('-');for(let i=0;i<(window.extraDate?2:1);i++){const b=document.createElement('button');b.type='button';b.className='datepicker-day-button selected';b.dataset.year=year;b.dataset.month=Number(month)-1;b.dataset.day=Number(day)+i;root.append(b)}}
</script>`;

export {product,target,options,parent,eventHTML};
